def angular_fv(e,gamma=.67,points=61,extent=7.,averaged=False):
    ta=e['temperature_a'];tb=e['temperature_b'];lam=e['relaxation_rate'];eta=e['flux_fraction'];width=extent*np.sqrt(max(ta,tb));edges=np.linspace(-width,width,points+1);x=(edges[1:]+edges[:-1])/2;n=points**2
    assert e['angular_speed']==0.
    v,g=np.meshgrid(x,x,indexing='ij');v=v.ravel();g=g.ravel();rows=np.arange(n);swap=rows.reshape(points,points).T.ravel();permutation=csr_matrix((np.ones(n),(rows,swap)),shape=(n,n))
    av=kron(ou_grid(edges,gamma,ta),eye(points),format='csr');ag=kron(eye(points),ou_grid(edges,lam,tb),format='csr');L=av+ag+diags(3.6*((1-eta)+eta*abs(v-g)))@(permutation-eye(n))
    system=L.T.tolil();system[n//2,:]=np.ones(n);target=np.zeros(n);target[n//2]=1.;p=spsolve(system.tocsc(),target)
    coo=ag.tocoo();energy=.5*g*g;marks=energy[coo.row]-energy[coo.col]
    derivatives=[csr_matrix((coo.data*marks**k,(coo.row,coo.col)),shape=(n,n)) for k in [1,2,3]]
    A1,A2,A3=derivatives;eps=e.get('detector_contrast',0.);harmonic=e.get('detector_harmonic',1);ones=np.ones(n)
    w={0:1.,-1:eps/2,1:eps/2};w2={0:1+eps*eps/2,-1:eps,1:eps,-2:eps*eps/4,2:eps*eps/4}
    ns=[0] if averaged else [-1,0,1];mean=float(p@(A1@ones));pivot=int(np.argmax(p))
    def invert(mode,rhs):
        if mode:return spsolve((L+diags(1j*mode*harmonic*v)).tocsc(),rhs)
        system=L.astype(complex).tolil();system[pivot,:]=p;rhs=rhs.copy();rhs[pivot]=0.;return spsolve(system.tocsc(),rhs)
    r1={mode:invert(mode,(mean*ones if mode==0 else np.zeros(n))-w[mode]*(A1@ones)) for mode in ns}
    c2=float(np.real(p@(w2[0]*(A2@ones)+2*sum(w[-mode]*(A1@r1[mode]) for mode in ns))))
    r2={mode:invert(mode,(c2*ones if mode==0 else np.zeros(n))+2*mean*r1[mode]-2*sum(w.get(mode-j,0.)*(A1@r1[j]) for j in ns)-w2[mode]*(A2@ones)) for mode in ns}
    c3=float(np.real(p@(3*sum(w[-mode]*(A1@r2[mode])+w2[-mode]*(A2@r1[mode]) for mode in ns)+(1+1.5*eps*eps)*(A3@ones))))
    return dict(mean=mean,noise=c2,third_cumulant=c3,minimum_probability=float(p.min()))


ungated_predict=predict
@lru_cache(512)
def gated_state(temperature_a,temperature_b,relaxation_rate,flux_fraction,contrast,harmonic,drag,points,extent):
    e=dict(temperature_a=temperature_a,temperature_b=temperature_b,relaxation_rate=relaxation_rate,
           flux_fraction=flux_fraction,angular_speed=0.,detector_contrast=contrast,detector_harmonic=harmonic)
    return angular_fv(e,drag,points,extent)

def predict(experiments,drag=TRUE_PARAMETER,points=81,extent=7.):
    result=[]
    for e in experiments:
        if not e.get('detector_contrast',0.):
            result.append(ungated_predict([e],drag,points,extent)[0]);continue
        settings=(e['temperature_a'],e['temperature_b'],e['relaxation_rate'],e['flux_fraction'],
                  e['detector_contrast'],e.get('detector_harmonic',1),drag)
        a=gated_state(*settings,points,extent);b=gated_state(*settings,2*points,extent)
        stat=e.get('statistic','mean');result.append((4*b[stat]-a[stat])/3)
    return np.array(result)

def gated_experiment(ta=1.8,tb=.4,lam=2.,eta=.7,contrast=.8,harmonic=1,statistic='third_cumulant'):
    return dict(temperature_a=ta,temperature_b=tb,relaxation_rate=lam,flux_fraction=eta,angular_speed=0.,flip_rate=1.2,
                detector_contrast=contrast,detector_harmonic=harmonic,statistic=statistic)

HIDDEN['angle_gated_hot_rotor_third']=[gated_experiment(ta=ta,tb=tb,lam=lam,eta=eta,contrast=c,harmonic=k)
    for ta,tb,lam,eta,c,k in [(1.8,.4,2.,.7,.8,1),(2.,.4,3.,1.,.7,2),(1.6,.6,.8,0.,.8,1),(1.8,.5,1.3,.4,.6,3)]]
HIDDEN['angle_gated_cold_rotor_third']=[gated_experiment(ta=ta,tb=tb,lam=lam,eta=eta,contrast=c,harmonic=k)
    for ta,tb,lam,eta,c,k in [(.4,1.4,2.,.7,.8,1),(.4,1.2,3.,1.,.7,2),(.6,1.4,.8,0.,.8,1),(.5,1.3,1.3,.4,.6,3)]]
HIDDEN['angle_gated_noise']=[dict(e,statistic='noise') for name in ['angle_gated_hot_rotor_third','angle_gated_cold_rotor_third'] for e in HIDDEN[name]]
HIDDEN['angle_gated_mean_and_equilibrium']=[dict(e,statistic='mean') for name in ['angle_gated_hot_rotor_third','angle_gated_cold_rotor_third'] for e in HIDDEN[name]]+[
    gated_experiment(ta=t,tb=t,eta=eta,contrast=.8,harmonic=k,statistic='noise') for t,eta,k in [(.4,0.,1),(1.2,1.,2)]]
